-- DISPOSABLE DATABASE ONLY. Run after review bootstrap/seed and the migration chain.
-- All synthetic data and source edits roll back at the end.
begin;
create or replace function public.check_assert(ok boolean,message text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'ASSERTION FAILED: %',message;end if;end$$;
reset role;
insert into public.ngn_cases(id,case_number,topic,title,intro,tabs,published) values ('60000000-0000-0000-0000-000000000001',1,'Antepartum','Private diagnosis title','Patient story','{"Notes":"Case notes"}',true);
insert into public.ngn_items(id,case_id,item_number,item_type,stem,content,published)
select ('70000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'60000000-0000-0000-0000-000000000001',n,'Multiple Choice','Live case item','{"options":["Assess"]}',true from generate_series(1,6) n;
insert into public.ngn_answers(item_id,case_id,answer,answer_text,rationale) select id,case_id,'{"correct":["A"]}','Assess','Live rationale' from public.ngn_items;
select check_assert(not has_function_privilege('authenticated','public.start_mixed_exam_attempt(uuid,text,jsonb,text)','execute'),'students cannot supply snapshots or keys');
select check_assert(not has_table_privilege('authenticated','public.exam_case_responses','insert'),'students cannot invent case scores');
select check_assert(not has_table_privilege('authenticated','public.exam_case_responses','update'),'students cannot edit case scores');
select set_config('test.mixed_items',$payload$[{"question_id": "20000000-0000-0000-0000-000000000001", "source_kind": "question", "source_id": "20000000-0000-0000-0000-000000000001", "case_id": null, "question_snapshot": {"id": "20000000-0000-0000-0000-000000000001", "type": "single", "category": "Antepartum", "stem": "Frozen standalone", "options": [{"id": "a", "label": "Assess"}]}, "solution_snapshot": {"answer_key": "a", "rationale": "Frozen standalone rationale"}}, {"question_id": "80000000-0000-0000-0000-000000000001", "source_kind": "ngn_case", "source_id": "70000000-0000-0000-0000-000000000001", "case_id": "60000000-0000-0000-0000-000000000001", "question_snapshot": {"id": "80000000-0000-0000-0000-000000000001", "type": "single", "category": "Antepartum", "stem": "Frozen case item 1", "options": [{"id": "o1", "label": "Assess"}], "case_context": {"case_id": "60000000-0000-0000-0000-000000000001", "item_id": "70000000-0000-0000-0000-000000000001", "case_number": 1, "item_number": 1, "item_count": 6}}, "solution_snapshot": {"answer_key": "o1", "rationale": "Frozen case rationale"}}, {"question_id": "80000000-0000-0000-0000-000000000002", "source_kind": "ngn_case", "source_id": "70000000-0000-0000-0000-000000000002", "case_id": "60000000-0000-0000-0000-000000000001", "question_snapshot": {"id": "80000000-0000-0000-0000-000000000002", "type": "single", "category": "Antepartum", "stem": "Frozen case item 2", "options": [{"id": "o1", "label": "Assess"}], "case_context": {"case_id": "60000000-0000-0000-0000-000000000001", "item_id": "70000000-0000-0000-0000-000000000002", "case_number": 1, "item_number": 2, "item_count": 6}}, "solution_snapshot": {"answer_key": "o1", "rationale": "Frozen case rationale"}}, {"question_id": "80000000-0000-0000-0000-000000000003", "source_kind": "ngn_case", "source_id": "70000000-0000-0000-0000-000000000003", "case_id": "60000000-0000-0000-0000-000000000001", "question_snapshot": {"id": "80000000-0000-0000-0000-000000000003", "type": "single", "category": "Antepartum", "stem": "Frozen case item 3", "options": [{"id": "o1", "label": "Assess"}], "case_context": {"case_id": "60000000-0000-0000-0000-000000000001", "item_id": "70000000-0000-0000-0000-000000000003", "case_number": 1, "item_number": 3, "item_count": 6}}, "solution_snapshot": {"answer_key": "o1", "rationale": "Frozen case rationale"}}, {"question_id": "80000000-0000-0000-0000-000000000004", "source_kind": "ngn_case", "source_id": "70000000-0000-0000-0000-000000000004", "case_id": "60000000-0000-0000-0000-000000000001", "question_snapshot": {"id": "80000000-0000-0000-0000-000000000004", "type": "single", "category": "Antepartum", "stem": "Frozen case item 4", "options": [{"id": "o1", "label": "Assess"}], "case_context": {"case_id": "60000000-0000-0000-0000-000000000001", "item_id": "70000000-0000-0000-0000-000000000004", "case_number": 1, "item_number": 4, "item_count": 6}}, "solution_snapshot": {"answer_key": "o1", "rationale": "Frozen case rationale"}}, {"question_id": "80000000-0000-0000-0000-000000000005", "source_kind": "ngn_case", "source_id": "70000000-0000-0000-0000-000000000005", "case_id": "60000000-0000-0000-0000-000000000001", "question_snapshot": {"id": "80000000-0000-0000-0000-000000000005", "type": "single", "category": "Antepartum", "stem": "Frozen case item 5", "options": [{"id": "o1", "label": "Assess"}], "case_context": {"case_id": "60000000-0000-0000-0000-000000000001", "item_id": "70000000-0000-0000-0000-000000000005", "case_number": 1, "item_number": 5, "item_count": 6}}, "solution_snapshot": {"answer_key": "o1", "rationale": "Frozen case rationale"}}, {"question_id": "80000000-0000-0000-0000-000000000006", "source_kind": "ngn_case", "source_id": "70000000-0000-0000-0000-000000000006", "case_id": "60000000-0000-0000-0000-000000000001", "question_snapshot": {"id": "80000000-0000-0000-0000-000000000006", "type": "single", "category": "Antepartum", "stem": "Frozen case item 6", "options": [{"id": "o1", "label": "Assess"}], "case_context": {"case_id": "60000000-0000-0000-0000-000000000001", "item_id": "70000000-0000-0000-0000-000000000006", "case_number": 1, "item_number": 6, "item_count": 6}}, "solution_snapshot": {"answer_key": "o1", "rationale": "Frozen case rationale"}}]$payload$,false);
select set_config('test.mixed_responses',$payload$[{"question_id": "20000000-0000-0000-0000-000000000001", "response": "a", "earned": 1, "possible": 1}, {"question_id": "80000000-0000-0000-0000-000000000001", "response": "o1", "earned": 0, "possible": 1}, {"question_id": "80000000-0000-0000-0000-000000000002", "response": "o1", "earned": 1, "possible": 1}, {"question_id": "80000000-0000-0000-0000-000000000003", "response": "o1", "earned": 1, "possible": 1}, {"question_id": "80000000-0000-0000-0000-000000000004", "response": "o1", "earned": 1, "possible": 1}, {"question_id": "80000000-0000-0000-0000-000000000005", "response": "o1", "earned": 1, "possible": 1}, {"question_id": "80000000-0000-0000-0000-000000000006", "response": "o1", "earned": 1, "possible": 1}]$payload$,false);
set role service_role;
select public.mixed_exam_session_version() as version \gset
select public.start_mixed_exam_attempt('10000000-0000-0000-0000-000000000001','test',current_setting('test.mixed_items')::jsonb,'Combined exam') as opened \gset
select set_config('test.mixed_attempt',:'opened'::jsonb->>'attemptId',false);
select check_assert(jsonb_array_length(:'opened'::jsonb->'questions')=7,'one standalone plus six case items');
select check_assert(:'opened' not like '%answer_key%' and :'opened' not like '%rationale%' and :'opened' not like '%Private diagnosis%','no solution or diagnosis-title leaks');
select check_assert((select array_agg((question_snapshot->'case_context'->>'item_number')::integer order by position)=array[1,2,3,4,5,6] from public.exam_review_items where attempt_id=current_setting('test.mixed_attempt')::uuid and source_kind='ngn_case'),'all six case items together in order');
reset role;
set role authenticated;set request.jwt.claim.sub='10000000-0000-0000-0000-000000000001';
select check_assert((select count(*)=0 from public.exam_review_items where attempt_id=current_setting('test.mixed_attempt')::uuid),'pending mixed keys hidden');
reset role;
update public.questions set stem='Edited live standalone' where id='20000000-0000-0000-0000-000000000001';
update public.ngn_items set stem='Edited live case' where case_id='60000000-0000-0000-0000-000000000001';update public.ngn_answers set rationale='Edited live rationale' where case_id='60000000-0000-0000-0000-000000000001';
select check_assert((select question_snapshot->>'stem'='Frozen case item 1' and solution_snapshot->>'rationale'='Frozen case rationale' from public.exam_review_items where attempt_id=current_setting('test.mixed_attempt')::uuid and position=2),'question and rationale snapshots survive source edits');
set role service_role;
select public.complete_exam_review_attempt(current_setting('test.mixed_attempt')::uuid,'10000000-0000-0000-0000-000000000001',current_setting('test.mixed_responses')::jsonb,30) as finished \gset
select check_assert((:'finished'::jsonb->>'earned')::int=6 and (:'finished'::jsonb->>'possible')::int=7,'one total score');
select check_assert((select count(*)=1 from public.exam_responses where attempt_id=current_setting('test.mixed_attempt')::uuid),'standalone progress uses existing table');
select check_assert((select count(*)=6 from public.exam_case_responses where attempt_id=current_setting('test.mixed_attempt')::uuid),'all case responses saved separately');
select public.complete_exam_review_attempt(current_setting('test.mixed_attempt')::uuid,'10000000-0000-0000-0000-000000000001','[]',0) as repeated \gset
select check_assert(:'repeated'::jsonb=:'finished'::jsonb,'repeated submission returns original score');
reset role;set role authenticated;set request.jwt.claim.sub='10000000-0000-0000-0000-000000000001';
select check_assert((select count(*)=7 from public.exam_review_items where attempt_id=current_setting('test.mixed_attempt')::uuid),'owner can review all completed items');
select check_assert((select count(*)=6 from public.exam_case_responses where attempt_id=current_setting('test.mixed_attempt')::uuid),'owner can review case answers');
set request.jwt.claim.sub='10000000-0000-0000-0000-000000000002';
select check_assert((select count(*)=0 from public.exam_attempts where id=current_setting('test.mixed_attempt')::uuid),'other student cannot read attempt');
select check_assert((select count(*)=0 from public.exam_case_responses where attempt_id=current_setting('test.mixed_attempt')::uuid),'other student cannot read case responses');
select check_assert((select count(*)=0 from public.exam_review_items where attempt_id=current_setting('test.mixed_attempt')::uuid),'other student cannot read snapshots');
reset role;
do $$declare before_count integer;begin
 select count(*) into before_count from public.exam_attempts;
 begin perform public.start_mixed_exam_attempt('10000000-0000-0000-0000-000000000001','test',current_setting('test.mixed_items')::jsonb-6,'Incomplete');raise exception 'Expected partial-case rejection';exception when sqlstate '22023' then null;end;
 perform check_assert((select count(*)=before_count from public.exam_attempts),'invalid case does not create attempt');
 begin update public.exam_review_items set question_snapshot='{}' where attempt_id=current_setting('test.mixed_attempt')::uuid;raise exception 'Expected immutability failure';exception when raise_exception then if sqlerrm='Expected immutability failure' then raise;end if;end;
end$$;
set role service_role;
select public.start_mixed_exam_attempt('10000000-0000-0000-0000-000000000001','study',$payload$[{"question_id": "80000000-0000-0000-0000-000000000001", "source_kind": "ngn_case", "source_id": "70000000-0000-0000-0000-000000000001", "case_id": "60000000-0000-0000-0000-000000000001", "question_snapshot": {"id": "80000000-0000-0000-0000-000000000001", "type": "single", "category": "Antepartum", "stem": "Frozen case item 1", "options": [{"id": "o1", "label": "Assess"}], "case_context": {"case_id": "60000000-0000-0000-0000-000000000001", "item_id": "70000000-0000-0000-0000-000000000001", "case_number": 1, "item_number": 1, "item_count": 6}}, "solution_snapshot": {"answer_key": "o1", "rationale": "Frozen case rationale"}}, {"question_id": "80000000-0000-0000-0000-000000000002", "source_kind": "ngn_case", "source_id": "70000000-0000-0000-0000-000000000002", "case_id": "60000000-0000-0000-0000-000000000001", "question_snapshot": {"id": "80000000-0000-0000-0000-000000000002", "type": "single", "category": "Antepartum", "stem": "Frozen case item 2", "options": [{"id": "o1", "label": "Assess"}], "case_context": {"case_id": "60000000-0000-0000-0000-000000000001", "item_id": "70000000-0000-0000-0000-000000000002", "case_number": 1, "item_number": 2, "item_count": 6}}, "solution_snapshot": {"answer_key": "o1", "rationale": "Frozen case rationale"}}, {"question_id": "80000000-0000-0000-0000-000000000003", "source_kind": "ngn_case", "source_id": "70000000-0000-0000-0000-000000000003", "case_id": "60000000-0000-0000-0000-000000000001", "question_snapshot": {"id": "80000000-0000-0000-0000-000000000003", "type": "single", "category": "Antepartum", "stem": "Frozen case item 3", "options": [{"id": "o1", "label": "Assess"}], "case_context": {"case_id": "60000000-0000-0000-0000-000000000001", "item_id": "70000000-0000-0000-0000-000000000003", "case_number": 1, "item_number": 3, "item_count": 6}}, "solution_snapshot": {"answer_key": "o1", "rationale": "Frozen case rationale"}}, {"question_id": "80000000-0000-0000-0000-000000000004", "source_kind": "ngn_case", "source_id": "70000000-0000-0000-0000-000000000004", "case_id": "60000000-0000-0000-0000-000000000001", "question_snapshot": {"id": "80000000-0000-0000-0000-000000000004", "type": "single", "category": "Antepartum", "stem": "Frozen case item 4", "options": [{"id": "o1", "label": "Assess"}], "case_context": {"case_id": "60000000-0000-0000-0000-000000000001", "item_id": "70000000-0000-0000-0000-000000000004", "case_number": 1, "item_number": 4, "item_count": 6}}, "solution_snapshot": {"answer_key": "o1", "rationale": "Frozen case rationale"}}, {"question_id": "80000000-0000-0000-0000-000000000005", "source_kind": "ngn_case", "source_id": "70000000-0000-0000-0000-000000000005", "case_id": "60000000-0000-0000-0000-000000000001", "question_snapshot": {"id": "80000000-0000-0000-0000-000000000005", "type": "single", "category": "Antepartum", "stem": "Frozen case item 5", "options": [{"id": "o1", "label": "Assess"}], "case_context": {"case_id": "60000000-0000-0000-0000-000000000001", "item_id": "70000000-0000-0000-0000-000000000005", "case_number": 1, "item_number": 5, "item_count": 6}}, "solution_snapshot": {"answer_key": "o1", "rationale": "Frozen case rationale"}}, {"question_id": "80000000-0000-0000-0000-000000000006", "source_kind": "ngn_case", "source_id": "70000000-0000-0000-0000-000000000006", "case_id": "60000000-0000-0000-0000-000000000001", "question_snapshot": {"id": "80000000-0000-0000-0000-000000000006", "type": "single", "category": "Antepartum", "stem": "Frozen case item 6", "options": [{"id": "o1", "label": "Assess"}], "case_context": {"case_id": "60000000-0000-0000-0000-000000000001", "item_id": "70000000-0000-0000-0000-000000000006", "case_number": 1, "item_number": 6, "item_count": 6}}, "solution_snapshot": {"answer_key": "o1", "rationale": "Frozen case rationale"}}]$payload$,'Case only') as only_case \gset
select public.complete_exam_review_attempt((:'only_case'::jsonb->>'attemptId')::uuid,'10000000-0000-0000-0000-000000000001',$payload$[{"question_id": "80000000-0000-0000-0000-000000000001", "response": null, "earned": 0, "possible": 1}, {"question_id": "80000000-0000-0000-0000-000000000002", "response": null, "earned": 0, "possible": 1}, {"question_id": "80000000-0000-0000-0000-000000000003", "response": null, "earned": 0, "possible": 1}, {"question_id": "80000000-0000-0000-0000-000000000004", "response": null, "earned": 0, "possible": 1}, {"question_id": "80000000-0000-0000-0000-000000000005", "response": null, "earned": 0, "possible": 1}, {"question_id": "80000000-0000-0000-0000-000000000006", "response": null, "earned": 0, "possible": 1}]$payload$,30) as omitted \gset
select check_assert((:'omitted'::jsonb->>'earned')::int=0 and (:'omitted'::jsonb->>'possible')::int=6,'omitted case answers save zero points without dropping items');
select public.start_mixed_exam_attempt('10000000-0000-0000-0000-000000000001','test',current_setting('test.mixed_items')::jsonb,'Atomic combined') as atomic \gset
select set_config('test.mixed_atomic',:'atomic'::jsonb->>'attemptId',false);
reset role;
create function public.fail_test_case_insert() returns trigger language plpgsql as $$begin if new.attempt_id=current_setting('test.mixed_atomic')::uuid then raise check_violation using message='Synthetic case response failure';end if;return new;end$$;
create trigger fail_case_insert before insert on public.exam_case_responses for each row execute function public.fail_test_case_insert();
do $$begin
 begin perform public.complete_exam_review_attempt(current_setting('test.mixed_atomic')::uuid,'10000000-0000-0000-0000-000000000001',current_setting('test.mixed_responses')::jsonb,15);raise exception 'Expected insert failure';exception when check_violation then null;end;
 perform check_assert((select count(*)=0 from public.exam_responses where attempt_id=current_setting('test.mixed_atomic')::uuid),'case insert failure rolls back standalone responses');
 perform check_assert((select count(*)=0 from public.exam_case_responses where attempt_id=current_setting('test.mixed_atomic')::uuid),'case insert failure leaves no case responses');
 perform check_assert((select completed_at is null and earned=0 and possible=0 from public.exam_attempts where id=current_setting('test.mixed_atomic')::uuid),'case insert failure cannot leave a completed score');
end$$;
drop trigger fail_case_insert on public.exam_case_responses;drop function public.fail_test_case_insert();
select check_assert(not exists(select id,user_id,mode,earned,possible,duration_seconds,created_at,completed_at from public.exam_attempts where id in(select id from baseline_attempts) except select * from baseline_attempts),'all original historical scores unchanged');
select 'PASS combined exams: grouping, private keys, RLS ownership, archived content, one score, both response stores, omissions, idempotency, full rollback, old scores unchanged' as result;

rollback;
